WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (183::BIGINT, 'El profesor es demasiado bueno. Explica ciencias del movimiento humano y física aplicada a la natación. Da buenas indicaciones, pero sí es bastante estricto. Nota que saqué: 95'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2026-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'e49cb847d2fd1b2b69cc17c91cfdd00e1f990b06aa70f87ffa396ab29beda993'::TEXT, ARRAY[492]::BIGINT[]),
    (183::BIGINT, 'Es un profe muy chill, y buena gente. Da ayuda de vez en cuando, aunque no tanta. Es bueno si no sabe nadar, aunque dudo que se vuelva bueno si no tiene bases. El examen algunos lo vieron difícil pero en realidad solo toma práctica en las últimas semanas. Da 5% extra con rellenar un formulario'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '83d5aa7c2dde032ae0dc9e25bb071a8b31a6d8d8f57c98b7e522f6e6c1a60616'::TEXT, ARRAY[492]::BIGINT[]),
    (183::BIGINT, 'Si vas a llevar natación, si eres principiante en nadar, mejor busque a otro profesor porque su examen es nadar muchas piscinas continuas sin descanso, y es demasiado agotador. Hay mejores opciones de profesores.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2026-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'bf9717de9341958c042864d16049c213b8ef02c60a3a4d93fa9ae2bd22446b87'::TEXT, ARRAY[492]::BIGINT[]),
    (183::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, '0fb1d1b9acc630a454afcbd87b6f1930bdb1123be3b8ffcb7c5d42062005b697'::TEXT, ARRAY[492]::BIGINT[]),
    (183::BIGINT, 'Tal vez sea porque odio natación, el no es mal profe pero el curso es deprimente'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Pocos exámenes', 'Exámenes retadores']::TEXT[], '2025-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'd3962e7daef5105406056efc80c003a4b196bb0fa279cd1cad104c3996c7903e'::TEXT, ARRAY[492]::BIGINT[]),
    (183::BIGINT, 'Super buen profe, si no sabes nadar, te va a ayudar y sus asistentes (los que me tocaron) fueron muy buenos, además te ayuda a corregir cualquier aspecto de una forma honesta y buena. Les recomiendo practicar el examen final si ya saben nadar, desde el DIA 1, ya que es muy desgastante el examen'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '5ac3123af2161a2c39d62f994d2926a4df9ce216a130ce5bd19e85dbc5948712'::TEXT, ARRAY[492]::BIGINT[]),
    (183::BIGINT, 'Muy buena nota, le interesa que la gente del tec tenga una vida mas sana'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2025-07-12T00:00:00+00:00'::TIMESTAMPTZ, '21c7afaf0c2b2d48be7be427b4ecf687be31cb4a1276a6e6cac175a4f64ca59d'::TEXT, ARRAY[493]::BIGINT[]),
    (183::BIGINT, 'Es muy buen profe se preocupa porque de verdad uno aprenda y la pase bien en la clase'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'b9fe0caf3d3419160cca688091abd26f1d8155404831ea5bcf4e2ce604c325d1'::TEXT, ARRAY[492]::BIGINT[]),
    (183::BIGINT, 'Te enseña a nadar desde 0 y si eres avanzado te pone practicas más difíciles. Si tiene la posibilidad ni lo piense.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-29T00:00:00+00:00'::TIMESTAMPTZ, '0a3d64ac12b1a3b85127572036f17008547fbafea632d81d538c04fc8975c888'::TEXT, ARRAY[492]::BIGINT[]),
    (183::BIGINT, 'Si llevas el curso virtual, debes de tener mucho orden con la entrega de los forms, porque es algo progresivo y puedes perder mucho porcentaje de la nota, no te va a tomar mucho tiempo haciendo los forms, pero tienes que tener mucho orden y acordarse de hacerlos'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '50fcce8278d241135d04aa5ba5fcc0b085491d7b947d0c83960f8fac463f9a73'::TEXT, ARRAY[493]::BIGINT[]),
    (183::BIGINT, 'Es muy exigente, siempre hay que entregar forms de ejercicios. Además, cuenta en la calificación la participación en clase, y no lo deja entrar a uno como oyente, por lo que si aceptan inclusiones y perdió lo de la primera clase porque a él no le da la gana reponerlo, es poco comprensivo.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '725b69d9e0146ea3537993f51ff58de4cd71992610367d3175ce084cf72ab31b'::TEXT, ARRAY[493]::BIGINT[]),
    (183::BIGINT, 'Es buen profe, lo recomiendo, aunque para ser 0 créditos si te exige cierto nivel en forms y demás, aunque aprendes cosas esenciles como RCP.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'bad6e7bcb5e8e9500d71ca12c272c610a7301c197980859d8b77582992a06db5'::TEXT, ARRAY[492]::BIGINT[]),
    (183::BIGINT, 'Tiene un gran conocimiento en natacion; sin embargo en las lecciones virtuales es muy estricto con los forms comparado con otros profesores.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '1e45af3a8aa6b1ebb24c717932998bbac5eccab2860df20f60408786b38b9a43'::TEXT, ARRAY[492]::BIGINT[]),
    (183::BIGINT, 'Es muy estricto, promueve el respeto y el trabajo en equipo. Si se asiste a todas las clases el curso se pasa solo. PD: Las primeras clases son de acondicionamiento físico'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '69e09df9ba4adad6586f978bc26c734aa29bca3fd5d3f6dcd7ff9f2477bf875a'::TEXT, ARRAY[495]::BIGINT[]),
    (183::BIGINT, 'Es un excelente profesor'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2019-02-12T00:00:00+00:00'::TIMESTAMPTZ, 'e0e6ce97ebef39b4574640748550a2842e7a562e851a11c404102350ccfad50a'::TEXT, ARRAY[493]::BIGINT[]),
    (183::BIGINT, 'Profe mas exigente del resto, examen final es nadar sin parar, la materia es muy chiva y se aprende. Si no sabe mucho el que más ayuda es el asistente.Pd: Ahora si van a conocer qué es el frio en realidad!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'b0cf88d79530880fb1f707874f54e44dc5a3f4ee05a97892ab960f5307ec018f'::TEXT, ARRAY[492]::BIGINT[]),
    (183::BIGINT, 'Exige que le pongas, el hace su trabajo bien. No muy amigable pero con que hagas las cosas bien, pasas. Sabe del tema y normalmente no ayuda mucho a los que no saben nadar, ese trabajo lo hacen sus asistentes. NOTA: QUE FRIÓ!!!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-01T00:00:00+00:00'::TIMESTAMPTZ, '3b1b540803a3ef377ee0439f95adfb961fc9f05890f7e4feffad1c347bca27a4'::TEXT, ARRAY[492]::BIGINT[]),
    (183::BIGINT, 'El peor profe si uno no sabe nadar, no inspira confianza'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('15','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-16T00:00:00+00:00'::TIMESTAMPTZ, '9148d87f714a6751505288ae1a04a86ce0d5024d026c15b0213027d1178a7610'::TEXT, ARRAY[492]::BIGINT[]),
    (183::BIGINT, 'Es muy relajado, simplemente hay que hacer las cosas bien en las clases y se pasa sola, se nota que le gusta bastante la clase que da. Es comprensivo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'bd930fccb7f9bc0766bc4e0892142a7c24b8caee4d400ef7981dc21e8fb09044'::TEXT, ARRAY[584]::BIGINT[]),
    (183::BIGINT, 'Le brinda apoyo a los que aún no saben nadar, sin embargo, es un poco exigente en cuanto al hecho que uno no puede quedarse descansando un momento, pero sí toma en cuenta el avance que uno tiene durante el curso y de acuerdo a eso lo evalúa en el examen.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, '20174164cad78c93c691b56d1a3193d431364ea568570e9322e2b7e8a00e84e2'::TEXT, ARRAY[492]::BIGINT[]),
    (183::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-10-20T00:00:00+00:00'::TIMESTAMPTZ, 'd49878456872604d97b313faa6674ed9481f351ab05d00ecdcd2c1fe51e64c29'::TEXT, ARRAY[584]::BIGINT[]),
    (183::BIGINT, 'Le falta mucho como profesor, en el ámbito educativo, y muy poco comprensible.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-04T00:00:00+00:00'::TIMESTAMPTZ, '68a5fe43dc51db1eca6b4b7e9971b9641208103ae7520158af3a5a4b1fc7441b'::TEXT, ARRAY[584]::BIGINT[]),
    (183::BIGINT, 'Es un pedante, inicialmente se muestra pura vida pero luego si uno se enferma es muy poco comprensible.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-10-11T00:00:00+00:00'::TIMESTAMPTZ, 'baf39b2b6ebaa7e9520a40d8f3897c37721641ef9dcb68634eefb0f5c6a52164'::TEXT, ARRAY[584]::BIGINT[]),
    (183::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-05-17T00:00:00+00:00'::TIMESTAMPTZ, 'dfc882859c2fa9b056f4c55ef8972dfeb75ab35fd574a93535a1cadf49956904'::TEXT, ARRAY[495]::BIGINT[]),
    (183::BIGINT, 'Un excelente profesor, muy atento por si le pasa algo a uno. Permite reponer clases con otros profesores y se debe ir a una sola actividad extracurricular.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-29T00:00:00+00:00'::TIMESTAMPTZ, '639a7a873c0590fe522cf9bed9c54ea662b6391cfe26192947ade76407f07487'::TEXT, ARRAY[492]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
